@Serializable
data class LootSource(
    /** raid:<zone>, dungeon:<zone>, vendor:<npc>, pvp:rank-<n>:<side>, pvp:title-rank-<n>:<side>, … */
    @SerialName("id") val id: String,
    @SerialName("kind") val kind: String,
    @SerialName("name") val name: String,
    @SerialName("items") val items: List<Int>? = null,
    @SerialName("trash") val trash: List<Int>? = null,
    @SerialName("bosses") val bosses: List<LootBoss>? = null,
    /** Item id -> percent; absent when unknown. */
    @SerialName("item_chances") val itemChances: Map<String, Double>? = null,
    @SerialName("zone_id") val zoneId: Int? = null,
    @SerialName("npc_id") val npcId: Int? = null,
    /** A phase name, or later; absent means open from launch. */
    @SerialName("opens") val opens: String? = null,
    @SerialName("profession") val profession: String? = null,
    @SerialName("faction_id") val factionId: Int? = null,
    @SerialName("standing") val standing: String? = null,
    @SerialName("rank") val rank: Int? = null,
    @SerialName("faction") val faction: String? = null,
    @SerialName("faction_source") val factionSource: String? = null,
    @SerialName("title") val title: String? = null,
    /** Era honor rank the item's title implies, on a pvp source with no rank lock (rank absent); eligibility only, not a lock. */
    @SerialName("title_rank") val titleRank: Int? = null,
    /** world_drop: the pool's level range. dungeon and raid: the instance's level range, the client's Group Finder row. */
    @SerialName("level_min") val levelMin: Int? = null,
    @SerialName("level_max") val levelMax: Int? = null,
    /** dungeon and raid: the instance's icon, a name under /data/{build}/icons (the API's zoneicons table: inv_misc_head_dragon_black for Onyxia's Lair, inv_misc_book_09 for an instance with none of its own). Written by the nightly loot run; absent on a build generated before it. */
    @SerialName("icon") val icon: String? = null,
    /** crafted only: item id -> the profession skill its recipe needs; an item with no known skill is absent. */
    @SerialName("required_skill") val requiredSkill: Map<String, Int>? = null,
    /** vendor and rep: where the seller stands (Booty Bay, The Barrens), curated; absent when unknown. */
    @SerialName("place") val place: String? = null,
    /** vendor only: item id -> its price when it is not gold; an item with no known price is absent. */
    @SerialName("item_costs") val itemCosts: Map<String, VendorCost>? = null,
    /** vendor only: the faction a quartermaster sells for, when every item it sells needs that faction's standing (faction_id beside it). */
    @SerialName("reputation") val reputation: String? = null,
    /** vendor only, beside reputation: item id -> the standing the client requires. */
    @SerialName("item_standings") val itemStandings: Map<String, String>? = null,
    @SerialName("rare_spawn") val rareSpawn: Boolean? = null,
    @SerialName("source_origin") val sourceOrigin: String? = null,
    @SerialName("source_note") val sourceNote: String? = null,
    @SerialName("reitemised_from") val reitemisedFrom: Map<String, Int>? = null,
)

/** The worn item the drop pushes out; null for an empty slot or one the class's item table cannot name. */
@Serializable
data class LootWornItem(
    @SerialName("item_id") val itemId: Int,
    @SerialName("name") val name: String,
    @SerialName("icon") val icon: String,
    @SerialName("quality") val quality: Int,
)

/** GET /v1/me's data (Go auth.Me): who you are, your characters, your guilds and what you may use. The apps gate a feature on entitlements only. */
@Serializable
data class Me(
    @SerialName("user") val user: AppUser,
    @SerialName("characters") val characters: List<AccountCharacter> = emptyList(),
    @SerialName("guilds") val guilds: List<AccountGuild> = emptyList(),
    @SerialName("entitlements") val entitlements: Entitlements,
    /** Unseen finished server runs, newest first, at most three; [] without server_sims. */
    @SerialName("finished_sims") val finishedSims: List<FinishedSim> = emptyList(),
    @SerialName("discord_link_available") val discordLinkAvailable: Boolean,
    @SerialName("discord_link") val discordLink: DiscordLink? = null,
    @SerialName("discord_link_suggested") val discordLinkSuggested: String? = null,
    /** Omitted until the account picks a main. */
    @SerialName("main_character_key") val mainCharacterKey: String? = null,
    /** True for an account in the creator program; omitted otherwise. */
    @SerialName("creator") val creator: Boolean? = null,
    /** The owner only: creator applications waiting; omitted at none. */
    @SerialName("creator_requests") val creatorRequests: Long? = null,
    /** When the account was last updated from Battle.net: a sign-in import, a refresh on a signed-in visit (at most hourly) or the background refresh of any of its characters (every 3 h for an account active in the last 14 days, else nightly). Every Battle.net sign-in imports the account's Forever characters (us, eu, tw) at any level; omitted when it never ran. */
    @SerialName("bnet_imported_at") val bnetImportedAt: String? = null,
    /** The last Battle.net import's state, omitted until a sign-in has tracked one. Sign-in records running when its import starts; the import ends inside the sign-in's 5 s budget or in a background run of up to 2 minutes, then records done (no error) or failed. A running state older than 3 minutes 5 seconds reads as failed: the instance running it stopped. Poll /v1/me while it reads running. */
    @SerialName("bnet_import") val bnetImport: BnetImport? = null,
    /** Omitted when the server has no sims store configured. */
    @SerialName("server_sims") val serverSims: ServerSimsUsage? = null,
    /** Omitted when the deployment has notifications off. */
    @SerialName("notifications") val notifications: MeNotifications? = null,
    @SerialName("seat") val seat: MeSeat? = null,
    /** Go auth.MeSeatOffer; omitted when none. */
    @SerialName("seat_offer") val seatOffer: JsonElement? = null,
    /** Go auth.MeEndedSeat; omitted when none. */
    @SerialName("ended_seat") val endedSeat: JsonElement? = null,
)

/** Omitted when the deployment has notifications off. */
@Serializable
data class MeNotifications(
    /** True when the one-click Discord connect is configured. */
    @SerialName("connect") val connect: Boolean,
    @SerialName("discord") val discord: DiscordBlock? = null,
)

